print(" *** Data type integer float string ***")
word = input("Enter a word : ")
try:
    num = int(word)
    print(f"{num} * 2 = {num * 2}")
except:
    try:
        num = float(word)
        print(f"{num:.3F} / 3 = {num / 3:.3f}")
    except:
        print(word, word, word)

print(" *** Water Supply Calculator ***")

unit = int(input("Total usage : "))

if unit <= 10:
    amount = unit * 5

elif unit <= 50:
    amount = (10 * 5) + (unit - 10) * 10

elif unit <= 100:
    amount = (10 * 5) + (40 * 10) + (unit - 50) * 12

elif unit <= 500:
    amount = (10 * 5) + (40 * 10) + (50 * 12) + (unit - 100) * 15

elif unit <= 1000:
    amount = (10 * 5) + (40 * 10) + (50 * 12) + (400 * 15) + (unit - 500) * 18

elif unit <= 5000:
    amount = (10 * 5) + (40 * 10) + (50 * 12) + (400 * 15) + (500 * 18) + (unit - 1000) * 20

else:
    amount = (
        (10 * 5)
        + (40 * 10)
        + (50 * 12)
        + (400 * 15)
        + (500 * 18)
        + (4000 * 20)
        + (unit - 5000) * 21
    )

print(f"Total Amount = {amount:,.2f} baht")
print("===== End of program =====")

n = int(input("Sum from 1 to : "))

if n < 1:
    print("Input Error")
else:
    total = 0
    i = 1
    while i <= n:
        total += i
        i += 1
    print(f"Sum from 1 to {n} is {total}")

