print(" *** Cross Letters ***")

try:
    n = int(input("Enter a positive odd number : "))

    if n <= 0 or n % 2 == 0:
            print("Invalid input !!!")
    else:
            if n <= 0 or n % 2 == 0:
                 print("Invalid input !!!")
            else:
                for i in range((n + 1) // 2):
                    for j in range(n):
                        if j == i:
                            print(chr(ord('A') + i % 26), end="")
                        elif j == n - 1 - i:
                            print(chr(ord('A') + (n - 1 - i) % 26), end="")
                        else:
                            print(" ", end="")
                    print()

                for i in range(n // 2 - 1, -1, -1):
                    for j in range(n):
                        if j == n - 1 - i:
                            print(chr(ord('A') + i % 26), end="")
                        elif j == i:
                            print(chr(ord('A') + (n - 1 - i) % 26), end="")
                        else:
                            print(" ", end="")
                    print()

                print("===== End of program =====")

except ValueError:
    print("Invalid input !!!")
